'use strict';

const path = require('path');
const cds = require('@sap/cds');

function grepCached(pattern, files, cache) {
  let re;
  try { re = new RegExp(pattern, 'gm'); } catch { return []; }
  const matches = [];
  for (const file of files) {
    const content = cache.get(file);
    if (!content) continue;
    matches.push(...grepContent(re, content, path.relative(cds.root, file)));
  }
  return matches;
}

function grepText(pattern, text, label) {
  let re;
  try { re = new RegExp(pattern, 'gm'); } catch { return []; }
  return grepContent(re, text, label);
}

function grepContent(re, content, label) {
  const matches = [];
  const lines = content.split('\n');
  let match;
  re.lastIndex = 0;

  while ((match = re.exec(content)) !== null) {
    const row = lineNumberAt(content, match.index);
    const lineStart = content.lastIndexOf('\n', match.index - 1) + 1;
    const col = match.index - lineStart;
    const startIdx = Math.max(0, row - 4);
    const endIdx = Math.min(lines.length - 1, row + 2);
    matches.push({
      file: label,
      line: row,
      col,
      context: match[0],
      surroundingLines: lines.slice(startIdx, endIdx + 1),
      source: 'regex',
    });
    if (match.index === re.lastIndex) re.lastIndex++;
  }

  return matches;
}

function lineNumberAt(content, offset) {
  let count = 1;
  for (let i = 0; i < offset; i++) {
    if (content.charCodeAt(i) === 10) count++;
  }
  return count;
}

function extractLeafPattern(dottedPattern) {
  const lastDot = dottedPattern.lastIndexOf('\\.');
  if (lastDot === -1) return dottedPattern;
  const leaf = dottedPattern.slice(lastDot + 2);
  return `\\b${leaf}\\b`;
}

function deduplicateMatches(matches) {
  const seen = new Set();
  return matches.filter(m => {
    const key = `${m.file}:${m.line}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function grepFiles(pattern, fileList) {
  const fs = cds.utils.fs;
  let re;
  try { re = new RegExp(pattern, 'gm'); } catch { return []; }
  const matches = [];
  for (const file of fileList) {
    let content;
    try { content = fs.readFileSync(file, 'utf8'); } catch { continue; }
    matches.push(...grepContent(re, content, path.relative(cds.root, file)));
  }
  return matches;
}

module.exports = {
  grepCached,
  grepFiles,
  grepText,
  grepContent,
  deduplicateMatches,
  extractLeafPattern,
};
